1	/**
2	 * Projection การคิดค่าบริการ (REQ-33 ถึง REQ-38)
3	 *
4	 * ==========================================================================
5	 * ข้อควรทราบที่สำคัญที่สุดของไฟล์นี้
6	 *
7	 * ยอดเงินไม่ได้ถูกเก็บไว้ที่ไหนเลย ทุกครั้งที่มีการเรียกดูใบแจ้งหนี้
8	 * ระบบจะอ่านเหตุการณ์ทั้งหมดตั้งแต่ต้นแล้วคำนวณใหม่หมด
9	 *
10	 * ผลที่ตามมา: การเปลี่ยนตรรกะการคำนวณในไฟล์นี้ หรือในโมดูลที่ไฟล์นี้เรียกใช้
11	 * จะทำให้ใบแจ้งหนี้ของ "ทุกเดือนย้อนหลัง" เปลี่ยนค่าไปด้วย
12	 * ทั้งที่ไม่มีข้อมูลใดถูกแก้ไขเลยแม้แต่แถวเดียว
13	 * ==========================================================================
14	 */
15	
16	import type { DomainEvent } from '../domain/events.ts';
17	import { replayAll, type BookingState } from '../domain/booking.ts';
18	import { findResource, NO_SHOW_CHARGE_RATIO } from '../domain/policy.ts';
19	import { billableMinutes, bookedMinutes } from '../lib/duration.ts';
20	
21	export interface InvoiceLine {
22	  bookingId: string;
23	  resourceId: string;
24	  billableMinutes: number;
25	  amountBaht: number;
26	  note?: string;
27	}
28	
29	export interface Invoice {
30	  userId: string;
31	  month: string;
32	  totalBaht: number;
33	  lines: InvoiceLine[];
34	}
35	
36	function monthOf(iso: string): string {
37	  return iso.slice(0, 7);
38	}
39	
40	function priceOne(b: BookingState): InvoiceLine | null {
41	  const resource = findResource(b.resourceId);
42	  if (!resource) return null;
43	
44	  // การจองที่ยกเลิกไม่คิดค่าบริการ (REQ-37)
45	  if (b.status === 'CANCELLED') return null;
46	
47	  if (b.status === 'COMPLETED' && b.actualStartAt && b.actualEndAt) {
48	    // คิดตามเวลาที่ใช้จริง (REQ-33) ปัดตามหน่วยที่กำหนด (REQ-35)
49	    const minutes = billableMinutes(b.actualStartAt, b.actualEndAt);
50	    return {
51	      bookingId: b.id,
52	      resourceId: b.resourceId,
53	      billableMinutes: minutes,
54	      amountBaht: round2((minutes / 60) * resource.hourlyRate),
55	    };
56	  }
57	
58	  if (b.status === 'NO_SHOW') {
59	    // จองแล้วไม่มาใช้ คิดตามสัดส่วนของเวลาที่จองไว้ (REQ-36)
60	    const minutes = bookedMinutes(b.startAt, b.endAt) * NO_SHOW_CHARGE_RATIO;
61	    return {
62	      bookingId: b.id,
63	      resourceId: b.resourceId,
64	      billableMinutes: minutes,
65	      amountBaht: round2((minutes / 60) * resource.hourlyRate),
66	      note: 'no-show',
67	    };
68	  }
69	
70	  return null;
71	}
72	
73	function round2(n: number): number {
74	  return Math.round(n * 100) / 100;
75	}
76	
77	/** เดือนที่นำการจองไปคิดเงิน อ้างตามเวลาเริ่มใช้จริง หรือเวลาที่จองไว้ถ้าไม่มา (REQ-38) */
78	function billingMonthOf(b: BookingState): string {
79	  return monthOf(b.actualStartAt ?? b.startAt);
80	}
81	
82	export function buildInvoice(events: DomainEvent[], userId: string, month: string): Invoice {
83	  const lines: InvoiceLine[] = [];
84	  for (const b of replayAll(events)) {
85	    if (b.userId !== userId) continue;
86	    if (billingMonthOf(b) !== month) continue;
87	    const line = priceOne(b);
88	    if (line) lines.push(line);
89	  }
90	  return {
91	    userId,
92	    month,
93	    totalBaht: round2(lines.reduce((s, l) => s + l.amountBaht, 0)),
94	    lines,
95	  };
96	}
97	
98	/** ยอดรวมของทั้งระบบในเดือนที่ระบุ — ใช้ตรวจว่าตัวเลขย้อนหลังถูกเปลี่ยนหรือไม่ */
99	export function totalRevenueForMonth(events: DomainEvent[], month: string): number {
100	  let total = 0;
101	  for (const b of replayAll(events)) {
102	    if (billingMonthOf(b) !== month) continue;
103	    const line = priceOne(b);
104	    if (line) total += line.amountBaht;
105	  }
106	  return round2(total);
107	}
